INSERT INTO counting_numbers SELECT target_id,unhex('7265616374696f6e733a6469736c696b65'),unhex('37303635633363333136663161633033363938306438623237636535376439326537333465623966326264663635373536646233646636303837396439613962'),countIf(JSONExtractString(body,unhex('74797065'))=unhex('6469736c696b65')) AS value FROM (SELECT *,`ref_value` AS target_id FROM (SELECT d.doc_id, d.author_key, d.posted_by, d.body, d.ref_value, d.tags, d.created_at, d.updated_at, d.ad_mode, d.ad_target, dg.group_id FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target FROM (SELECT doc_id, author_key, posted_by, body, ref_value, tags, created_at, updated_at, ad_mode, ad_target, deleted, row_number() OVER (PARTITION BY doc_id, author_key ORDER BY updated_at DESC) AS rn FROM documents WHERE collection_name = 'reactions') WHERE rn = 1 AND deleted = 0) d JOIN (SELECT doc_id, group_id FROM (SELECT doc_id, group_id, deleted, row_number() OVER (PARTITION BY doc_id, group_id ORDER BY updated_at DESC) AS rn FROM doc_groups WHERE group_id IN ('api.localhost/groups/users/rd42-u0000000/followers', 'api.localhost/groups/users/rd42-u0000001/followers', 'api.localhost/groups/users/rd42-u0000002/followers', 'api.localhost/groups/users/rd42-u0000003/followers', 'api.localhost/groups/users/rd42-u0000004/followers', 'api.localhost/groups/users/rd42-u0000005/followers', 'api.localhost/groups/users/rd42-u0000006/followers', 'api.localhost/groups/users/rd42-u0000007/followers', 'api.localhost/groups/users/rd42-u0000008/followers', 'api.localhost/groups/users/rd42-u0000009/followers', 'api.localhost/groups/users/rd42-u0000010/followers', 'api.localhost/groups/users/rd42-u0000011/followers', 'api.localhost/groups/users/rd42-u0000012/followers', 'api.localhost/groups/users/rd42-u0000013/followers', 'api.localhost/groups/users/rd42-u0000014/followers', 'api.localhost/groups/users/rd42-u0000015/followers', 'api.localhost/groups/users/rd42-u0614008/followers', 'api.localhost/groups/users/rd42-u0614009/followers', 'api.localhost/groups/users/rd42-u0614010/followers', 'api.localhost/groups/users/rd42-u0614011/followers', 'api.localhost/groups/users/rd42-u0980001/followers', 'api.localhost/groups/web10/discover')) WHERE rn = 1 AND deleted = 0) dg ON d.doc_id = dg.doc_id WHERE d.author_key NOT IN (SELECT user_key FROM (SELECT user_key, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'rd42-u0980001') AND (d.author_key, dg.group_id) NOT IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, blocked_key, deleted, row_number() OVER (PARTITION BY user_key, group_id, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'rd42-u0980001') AND NOT (d.author_key != 'rd42-u0980001' AND (d.author_key, dg.group_id) IN (SELECT user_key, group_id FROM (SELECT user_key, group_id, sharing_enabled, deleted, row_number() OVER (PARTITION BY user_key, group_id ORDER BY updated_at DESC) AS rn FROM user_group_sharing) WHERE rn = 1 AND deleted = 0 AND sharing_enabled = 0)) AND (d.doc_id, dg.group_id) NOT IN (SELECT doc_id, group_id FROM (SELECT group_id, doc_id, deleted, row_number() OVER (PARTITION BY group_id, doc_id ORDER BY updated_at DESC, deleted DESC) AS rn FROM group_hidden_docs) WHERE rn = 1 AND deleted = 0) AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0))) WHERE target_id!='' GROUP BY target_id HAVING value>0
